      const ax = c[0] + Math.cos(q) * R, ay = c[1] + Math.sin(q) * R, bq = -Math.PI / 2 + i / DOTN * TAU, bx = c[0] + Math.cos(bq) * 44, by = c[1] + Math.sin(bq) * 44;
      const x = lerp(ax, bx, g), y = lerp(ay, by, g), col = mixHex(CREAM, COAT.lit, g), al = on * (.35 + .65 * Math.max(lit * (1 - drop), g));
